namespace CSharpPracticum.Tasks.Level2;
public static class StringExtensions { public static bool IsPalindrome(this string s){string v=new(s.Where(char.IsLetterOrDigit).Select(char.ToLowerInvariant).ToArray());return v.SequenceEqual(v.Reverse());} public static int WordCount(this string s)=>s.Split((char[]?)null,StringSplitOptions.RemoveEmptyEntries).Length; public static string ReverseString(this string s)=>new(s.Reverse().ToArray()); }
internal class Task16_StringExtensions:ITask { public string Title=>"Задание 16: Методы расширения для string"; public string Description=>"Создать методы IsPalindrome, WordCount и ReverseString."; public string[] Requirements=>new[]{"Статический класс StringExtensions.","Методы public static с this string.","Показать вызов на 2–3 строках."}; public void Run(){foreach(string s in new[]{"А роза упала на лапу Азора","hello world","abc"})Console.WriteLine($"{s}: palindrome={s.IsPalindrome()}, words={s.WordCount()}, reverse={s.ReverseString()}");} }
